mapper.select:
SELECT u.id, u.username, u.display_name, u.bio, u.avatar_key FROM users u WHERE u.id <> #{viewerId} AND (lower(u.username) LIKE lower(#{pattern}) ESCAPE '\' OR lower(u.display_name) LIKE lower(#{pattern}) ESCAPE '\')
AND (lower(u.username), u.id) > (#{cursorKey}, #{cursorId})
ORDER BY lower(u.username), u.id LIMIT #{limit}
